#!/usr/bin/env bash
# Question 1: DaemonSet ${Q1_DS} is not running everywhere. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q1_NS}" delete daemonset "${Q1_DS}" "legacy-exporter" --ignore-not-found --wait=true >/dev/null
kubectl -n "${Q1_NS}" wait --for=delete pod -l "app in (${Q1_DS},legacy-exporter)" --timeout=90s >/dev/null 2>&1 || true
# Other DaemonSets a fault adds, one per line: they must still run at the end.
: > "/var/tmp/cka-q1.others"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: DaemonSet
metadata:
  name: ${Q1_DS}
  namespace: ${Q1_NS}
  labels: { app: ${Q1_DS} }
spec:
  selector:
    matchLabels: { app: ${Q1_DS} }
  updateStrategy:
    type: RollingUpdate
    rollingUpdate: { maxUnavailable: 1 }
  template:
    metadata:
      labels: { app: ${Q1_DS} }
    spec:
      nodeSelector: { cka.lab/hold: "yes" }
      tolerations:
        - { key: node-role.kubernetes.io/control-plane, operator: Exists, effect: NoSchedule }
      containers:
        - name: agent
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
          readinessProbe:
            httpGet: { path: /, port: 80 }
            periodSeconds: 5
          resources:
            requests: { cpu: 10m, memory: 16Mi }
EOF
kubectl -n "${Q1_NS}" get daemonset "${Q1_DS}" -o jsonpath='{.metadata.uid}' > "/var/tmp/cka-q1.uid"
chmod 644 "/var/tmp/cka-q1.uid" "/var/tmp/cka-q1.others"

case "${Q1_FAULT}" in
  image-typo)
    kubectl -n "${Q1_NS}" set image "daemonset/${Q1_DS}" agent=nginx:1.27-apline
    ;;
  readiness-port)
    kubectl -n "${Q1_NS}" patch daemonset "${Q1_DS}" --type=strategic -p '{"spec":{"template":{"spec":{"containers":[{"name":"agent","readinessProbe":{"httpGet":{"port":8080}}}]}}}}'
    ;;
  cp-toleration-typo)
    kubectl -n "${Q1_NS}" patch daemonset "${Q1_DS}" --type=strategic -p '{"spec":{"template":{"spec":{"tolerations":[{"key":"node-role.kubernetes.io/controlplane","operator":"Exists","effect":"NoSchedule"}]}}}}'
    ;;
  hostname-affinity)
    other=$(for w in "worker-1" "worker-2"; do [[ "$w" == "${Q1_WORKER}" ]] || echo "$w"; done)
    kubectl -n "${Q1_NS}" patch daemonset "${Q1_DS}" --type=strategic -p '{"spec":{"template":{"spec":{"affinity":{"nodeAffinity":{"requiredDuringSchedulingIgnoredDuringExecution":{"nodeSelectorTerms":[{"matchExpressions":[{"key":"kubernetes.io/hostname","operator":"In","values":["controlplane","'"$other"'"]}]}]}}}}}}}'
    ;;
  hostport-conflict)
    port=$(shuf -i 9100-9899 -n 1)
    kubectl apply -f - <<< '{"apiVersion":"apps/v1","kind":"DaemonSet","metadata":{"name":"legacy-exporter","namespace":"'"${Q1_NS}"'"},"spec":{"selector":{"matchLabels":{"app":"legacy-exporter"}},"template":{"metadata":{"labels":{"app":"legacy-exporter"}},"spec":{"containers":[{"name":"exporter","image":"registry.k8s.io/pause:3.10","ports":[{"containerPort":'"$port"',"hostPort":'"$port"'}],"resources":{"requests":{"cpu":"5m","memory":"8Mi"}}}]}}}}' >/dev/null
    kubectl -n "${Q1_NS}" rollout status "daemonset/legacy-exporter" --timeout=120s >/dev/null 2>&1 || true
    echo "legacy-exporter" >> "/var/tmp/cka-q1.others"
    kubectl -n "${Q1_NS}" patch daemonset "${Q1_DS}" --type=strategic -p '{"spec":{"template":{"spec":{"containers":[{"name":"agent","ports":[{"containerPort":80,"hostPort":'"$port"'}]}]}}}}'
    ;;
  worker-taint)
    kubectl taint node "${Q1_WORKER}" maintenance=planned:NoSchedule --overwrite >/dev/null
    ;;
  ondelete-stale)
    kubectl -n "${Q1_NS}" patch daemonset "${Q1_DS}" --type=strategic -p '{"spec":{"updateStrategy":{"type":"OnDelete","rollingUpdate":null},"template":{"spec":{"containers":[{"name":"agent","command":["nginx","-c","/etc/nginx/agent.conf","-g","daemon off;"]}]}}}}'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "${Q1_NS}" patch daemonset "${Q1_DS}" --type=json -p '[{"op":"remove","path":"/spec/template/spec/nodeSelector/cka.lab~1hold"}]'

case "${Q1_FAULT}" in
  image-typo)
    notready=0
    for _ in $(seq 1 10); do
      states="$(kubectl -n "${Q1_NS}" get pods -l "app=${Q1_DS}" -o jsonpath='{range .items[*]}{.status.phase} {.status.conditions[?(@.type=="Ready")].status} {.status.conditions[?(@.type=="PodScheduled")].status} {.status.containerStatuses[0].state.waiting.reason} {.status.containerStatuses[0].restartCount}{"\n"}{end}' 2>/dev/null)"
      if grep -qE '(ErrImagePull|ImagePullBackOff|CrashLoopBackOff|CreateContainerConfigError|CreateContainerError|RunContainerError)|[1-9][0-9]*$|^[A-Za-z]+ [A-Za-z]* False' <<< "$states"; then break; fi
      if kubectl -n "${Q1_NS}" get events --field-selector reason=FailedMount -o name 2>/dev/null | grep -q .; then break; fi
      if grep -qE '^Running False' <<< "$states"; then
        notready=$((notready + 1))
        (( notready >= 3 )) && break
      else
        notready=0
      fi
      sleep 2
    done
    ;;
  readiness-port)
    notready=0
    for _ in $(seq 1 10); do
      states="$(kubectl -n "${Q1_NS}" get pods -l "app=${Q1_DS}" -o jsonpath='{range .items[*]}{.status.phase} {.status.conditions[?(@.type=="Ready")].status} {.status.conditions[?(@.type=="PodScheduled")].status} {.status.containerStatuses[0].state.waiting.reason} {.status.containerStatuses[0].restartCount}{"\n"}{end}' 2>/dev/null)"
      if grep -qE '(ErrImagePull|ImagePullBackOff|CrashLoopBackOff|CreateContainerConfigError|CreateContainerError|RunContainerError)|[1-9][0-9]*$|^[A-Za-z]+ [A-Za-z]* False' <<< "$states"; then break; fi
      if kubectl -n "${Q1_NS}" get events --field-selector reason=FailedMount -o name 2>/dev/null | grep -q .; then break; fi
      if grep -qE '^Running False' <<< "$states"; then
        notready=$((notready + 1))
        (( notready >= 3 )) && break
      else
        notready=0
      fi
      sleep 2
    done
    ;;
  cp-toleration-typo)
    nodes=$(kubectl get nodes --no-headers | wc -l)
    for _ in $(seq 1 20); do
      want=$(kubectl -n "${Q1_NS}" get daemonset "${Q1_DS}" -o jsonpath='{.status.desiredNumberScheduled}')
      [[ -n "$want" && "$want" -lt "$nodes" ]] && break
      sleep 2
    done
    ;;
  hostname-affinity)
    nodes=$(kubectl get nodes --no-headers | wc -l)
    for _ in $(seq 1 20); do
      want=$(kubectl -n "${Q1_NS}" get daemonset "${Q1_DS}" -o jsonpath='{.status.desiredNumberScheduled}')
      [[ -n "$want" && "$want" -lt "$nodes" ]] && break
      sleep 2
    done
    ;;
  hostport-conflict)
    notready=0
    for _ in $(seq 1 10); do
      states="$(kubectl -n "${Q1_NS}" get pods -l "app=${Q1_DS}" -o jsonpath='{range .items[*]}{.status.phase} {.status.conditions[?(@.type=="Ready")].status} {.status.conditions[?(@.type=="PodScheduled")].status} {.status.containerStatuses[0].state.waiting.reason} {.status.containerStatuses[0].restartCount}{"\n"}{end}' 2>/dev/null)"
      if grep -qE '(ErrImagePull|ImagePullBackOff|CrashLoopBackOff|CreateContainerConfigError|CreateContainerError|RunContainerError)|[1-9][0-9]*$|^[A-Za-z]+ [A-Za-z]* False' <<< "$states"; then break; fi
      if kubectl -n "${Q1_NS}" get events --field-selector reason=FailedMount -o name 2>/dev/null | grep -q .; then break; fi
      if grep -qE '^Running False' <<< "$states"; then
        notready=$((notready + 1))
        (( notready >= 3 )) && break
      else
        notready=0
      fi
      sleep 2
    done
    ;;
  worker-taint)
    nodes=$(kubectl get nodes --no-headers | wc -l)
    for _ in $(seq 1 20); do
      want=$(kubectl -n "${Q1_NS}" get daemonset "${Q1_DS}" -o jsonpath='{.status.desiredNumberScheduled}')
      [[ -n "$want" && "$want" -lt "$nodes" ]] && break
      sleep 2
    done
    ;;
  ondelete-stale)
    for _ in $(seq 1 45); do
      want=$(kubectl -n "${Q1_NS}" get daemonset "${Q1_DS}" -o jsonpath='{.status.desiredNumberScheduled}')
      have=$(kubectl -n "${Q1_NS}" get pods -l app="${Q1_DS}" -o jsonpath='{range .items[*]}{.spec.containers[0].command}{"\n"}{end}' | grep -c agent.conf || true)
      [[ -n "$want" && "$want" -gt 0 && "$have" -ge "$want" ]] && break
      sleep 2
    done
    kubectl -n "${Q1_NS}" patch daemonset "${Q1_DS}" --type=json -p '[{"op":"remove","path":"/spec/template/spec/containers/0/command"}]'
    ;;
esac
